      "evidence": [
        {"sid": "P4.S0", "rel": "entails", "sub": "Older versions of SQLite could not read a WAL-mode database that was read-only"},
        {"sid": "P4.S1", "rel": "entails", "sub": "write access was required in order to read a WAL-mode database"}
      ],
      "check": null,
      "reasoning": "P4.S0 says older versions could not read a read-only WAL database; P4.S1 restates that write access was required."
    },
    {
      "id": "c1",
      "evidence": [
        {"sid": "P4.S1", "rel": "entails", "sub": "write access was required in order to read a WAL-mode database"},
        {"sid": "P4.S2", "rel": "entails", "sub": "relaxed beginning with SQLite version 3.22.0"}
      ],
      "check": null,
      "reasoning": "P4.S1 identifies the write-access constraint; P4.S2 says that constraint was relaxed starting at the stated version."
    },
    {
      "id": "c2",
      "evidence": [
        {"sid": "P5.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P5.S0 directly covers newer versions, read-only media, and the condition that one or more listed conditions hold."
    },
    {
      "id": "c3",
      "evidence": [
        {"sid": "P6.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P6.S0 recommends converting to DELETE mode before placing an image on read-only media."
    },
    {
      "id": "c4",
      "evidence": [
        {"sid": "P2.S2", "rel": "entails"},
        {"sid": "P2.S5", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P2.S2 says transactions over about 100MB favor rollback; P2.S5 later marks 3.11.0 as the change point for large-transaction efficiency."
    },
    {
      "id": "c5",
      "evidence": [
        {"sid": "P2.S5", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P2.S5 directly states the 3.11.0 cutoff and equal efficiency for large transactions."
    },
    {
      "id": "c6",
      "evidence": [
        {"sid": "P8.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P8.S0 gives the 3.7.4 start and says WAL operations can occur when shared memory is unavailable, subject to the exclusive-locking condition."
    },
    {
      "id": "c7",
      "evidence": [
        {"sid": "P8.S0", "rel": "entails", "sub": "as long as the locking_mode is set to EXCLUSIVE before the first attempted access"}
      ],
      "check": null,
      "reasoning": "P8.S0 makes exclusive locking before first access the stated condition for using WAL without shared memory."
    },
    {
      "id": "c8",
      "evidence": [
        {"sid": "P9.S2", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P9.S2 directly states that WAL mode raises the header format version bytes from 1 to 2."
    },
    {
      "id": "c9",
      "evidence": [
        {"sid": "P9.S2", "rel": "refutes", "sub": "prior to version 3.7.0"}
      ],
      "check": {"kind": "version", "left": "3.22.0", "op": ">", "right": "3.7.0"},
      "reasoning": "P9.S2 ties this error to versions prior to 3.7.0; 3.22.0 is newer, so the claim's older-than-3.22.0 threshold is too broad."
    },
    {
